function PVPArenaComponent:InitMansionsRoot()
    if self.mansionRootGo then return end
    if not string.isEmpty(MansionsPath) then
        local GameObject    = CS.UnityEngine.GameObject
        local go = GameObject.Find(MansionsRootName)
        if isNull(go) then
            go = KTool.CreateEmptyGameObject(nil, MansionsRootName, false)
        else
            KTool.DestroyGameObjectChildren(go)
        end
        self.mansionRootGo = go
        self.mansionGo = GameUtils.LoadBundleAsync(MansionsPath, go, false, true)
        local transform = self.mansionGo.transform
        local groupVenue = transform:Find(GroupVenueName)
        self.groupVenuePos = groupVenue.position
        local finalVenue = transform:Find(FinalVenueName)
        self.finalVenuePos = finalVenue.position
    end
end

