function PVPArenaComponent:InitResultDialogHistoryRecord()
    local pvpArenaEntryDojo = self:GetPVPArenaEntryDojo()
    local storeKey = string.format('%s_%s_', tostring(pvpArenaEntryDojo.seasonId), Constants.UICacheDataKeys.PVPArenaResultDialogHistoryRecord)
    if self.storeKey == storeKey then return end
    self.storeKey = storeKey
    local storeString = CfUtils.GetLocalData(storeKey, "")
    self.resultDialogHistoryRecord = string.isEmpty(storeString) and {} or table.deserialize(storeString)
end

function PVPArenaComponent:SetResultDialogHistoryRecord()
    CfUtils.WriteLocalData(self.storeKey, table.serialize(self.resultDialogHistoryRecord))
end

