---CalcGroupEndNumber
---计算小组赛结束时的人数
function PVPArenaComponent:InitContestData()
    ------------------------------
    --- 小组赛
    local numberOfContestants = self:GetNumberOfContestants()
    ---小组个数
    local groupCount = GroupCount
    ---每组人数
    local oneGroupCount = numberOfContestants / groupCount
    local tempOneGroupCount = oneGroupCount
    --- 小组赛 打多少轮
    local wheel = self:CalcWheel(tempOneGroupCount)

    --- 小组每轮范围
    local groupWheelScope = {}
    --- 每轮所有组的范围
    local allWheelScope = {}
    local totalNumber = 0
    local displayWheelCount = wheel + 1
    local signalCount = oneGroupCount
    for i = 1, displayWheelCount do
        local oneWheelNum = numberOfContestants / (2 ^ (i - 1))
        for index = 1, groupCount do
            groupWheelScope[index] = groupWheelScope[index] or {}
            table.insert(groupWheelScope[index], {1 + (checkInt(signalCount * (index - 1))) + totalNumber, checkInt(signalCount * index) + totalNumber})
        end
        local newTotalNumber = checkInt(totalNumber + oneWheelNum)
        table.insert(allWheelScope, { 1 + totalNumber, newTotalNumber})
        totalNumber = newTotalNumber
        signalCount = signalCount * 0.5
    end

    local groupTotalNumber = totalNumber
    local groupWheelCount  = wheel

    ------------------------------
    --- 最终赛
    --local finalWheelScope = {}
    local finalTotalNum = numberOfContestants / (2 ^ wheel)
    --- 最终赛人数
    totalNumber = totalNumber - finalTotalNum
    --- 最终赛 打多少轮
    wheel = self:CalcWheel(finalTotalNum)
    displayWheelCount = wheel + 1
    groupCount = finalTotalNum * 0.5
    signalCount = oneGroupCount
    for i = 1, displayWheelCount do
        local oneWheelNum = finalTotalNum / (2 ^ (i - 1)) * (i == wheel and 2 or 1)
        local oldTotalNumber = totalNumber
        totalNumber = checkInt(totalNumber + oneWheelNum)
        if i ~= 1 then
            table.insert(allWheelScope, {1 + oldTotalNumber, totalNumber})
        end

    end

    ------------------------------
    --- 缓存
    ---@field groupEndNumber number 小组赛结束人数
    self.groupEndNumber = groupTotalNumber
    ---@field groupWheelScope table<number, table> 小组赛轮数范围
    self.groupWheelScope = groupWheelScope
    ---@field groupWheelCount number 小组赛打了多少轮
    self.groupWheelCount = groupWheelCount
    ---@field allGroupScope table<number, table> 所有轮的范围
    self.allGroupScope = allWheelScope

    ---@field finalEndNumber number 最终赛结束人数
    self.finalEndNumber = totalNumber
    ---@field finalWheelCount number 最终赛赛打了多少轮
    self.finalWheelCount = wheel

    ---@field matchChartTotalNum number 对阵图总轮数
    self.matchChartTotalWheelNum = groupWheelCount + wheel + 1
end

---FillPVPArenaDojo
---填充数据
---@param jsonData table
---@return PVPArenaDojo
function PVPArenaComponent:FillPVPArenaDojo(jsonData)
    --- 服务端 对阵图 计算方式 是 先算正常情况 也就是 一直填充到 冠军位置 在算 第三 第四的位置
    --- 由于 冠军赛和季军赛 是一起打的 所以 这里需要吧 把冠军位置 移动到最后 保证没轮的位置信息连续性
    local map = checkTable(jsonData.map)
    if next(map) then
        ---1. 取出 最终赛结束有多少人 = 正常情况 + 2(第三和第四)
        local finalEndNumber = self.finalEndNumber

        ---2. 把冠军移动到最后 1 3 4 -> 3 4 1
        local championPositionData          = map[tostring(finalEndNumber - 2)]
        local thirdPlaceLeftPositionData    = map[tostring(finalEndNumber - 1)]
        local thirdPlaceRightPositionData   = map[tostring(finalEndNumber)]
        map[tostring(finalEndNumber-1)] = thirdPlaceRightPositionData
        map[tostring(finalEndNumber-2)] = thirdPlaceLeftPositionData
        map[tostring(finalEndNumber)]       = championPositionData

    end

    return self.pvpArenaDojo:Fill(jsonData)
end

function PVPArenaComponent:FillPVPArenaEntryDojo(jsonData)
