end

function PVPArenaComponent:InitCurWheel()
    local pvpArenaDojo  = self:GetPVPArenaDojo()
    local map           = pvpArenaDojo.map
    local positionCount = table.count(map)
    local wheel         = self:CalcDisplayWheelByPosition(positionCount)
    ---@field curWheel string 当前打了多少轮
    self.curWheel = wheel
    self.positionCount = positionCount
end

function PVPArenaComponent:InitSeasonFlag()
    local oldSeasonFlag = self:GetSeasonFlag()

    ---@type PVPArenaDojo
    local pvpArenaDojo = self:GetPVPArenaDojo()
    ---@type PVPArenaEntryDojo
    local pvpArenaEntryDojo = self:GetPVPArenaEntryDojo()
    local map          = checkTable(pvpArenaDojo.map)
    --- 是否是观众
    local isAudience   = checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience
    local seasonFlag = -1
    local mainPanelStatus
    ---@type Constants.PVPArenaSeasonStatus
    local seasonStatus = checkNumber(pvpArenaEntryDojo.seasonStatus)
    if seasonStatus == PVPArenaSeasonStatus.Closed then
        seasonFlag = PVPArenaSeasonFullStatus.Closed
        mainPanelStatus = PVPArenaMainPanelStatus.Closed

    elseif seasonStatus == PVPArenaSeasonStatus.Quiz then
        seasonFlag = PVPArenaSeasonFullStatus.Quiz
        if isAudience then
            local quizzed       = checkTable(pvpArenaDojo.quizzed)
            --- 投过几次票
            local quizNum       = table.count(quizzed)
            --- 竞猜票数量
            local quizTicketNum = checkNumber(pvpArenaDojo.quizTicketNum)
            --- 能投多少次
            local quizMaxNum    = quizNum + quizTicketNum

            local t = {
                [0] = PVPArenaMainPanelStatus.NoQuiz,
                [quizMaxNum] = PVPArenaMainPanelStatus.QuizComplete
            }
            mainPanelStatus = t[quizNum] or PVPArenaMainPanelStatus.NoQuizComplete

        else
            mainPanelStatus = PVPArenaMainPanelStatus.Ready

        end

    elseif seasonStatus <= PVPArenaSeasonStatus.Notice then
        seasonFlag = PVPArenaSeasonFullStatus.Notice
        mainPanelStatus = isAudience and PVPArenaMainPanelStatus.Notice or PVPArenaMainPanelStatus.Ready

    elseif seasonStatus == PVPArenaSeasonStatus.Battle then

        ---@type Constants.PVPArenaBattleStatus
        local battleStatus    = checkNumber(pvpArenaEntryDojo.battleStatus)
        local battleRound     = checkNumber(pvpArenaDojo.battleRound)

        local positionCount   = self.positionCount
        local curWheel        = self:GetCurWheel()
        local groupWheelCount = self:GetGroupWheelCount()
        local groupDisplayWheelCount  = groupWheelCount + 1

        --print("curWheel", curWheel)
        --print("battleRound", battleRound)
        --print("positionCount----->>>", positionCount, positionCount == self:GetGroupEndNumber(), battleStatus == PVPArenaBattleStatus.Wait)
        if positionCount == self:GetGroupEndNumber() and battleStatus == PVPArenaBattleStatus.Wait then
            seasonFlag = PVPArenaSeasonFullStatus.OffSeason
        elseif curWheel > groupDisplayWheelCount or (curWheel == groupDisplayWheelCount and battleRound == 1) then
            seasonFlag = PVPArenaSeasonFullStatus.Final
        else
            seasonFlag = PVPArenaSeasonFullStatus.Group
        end

        if isAudience then
            mainPanelStatus = PVPArenaMainPanelStatus.WatchTheMatch
        else
            mainPanelStatus = self:InitPlayerBattleMainPanelStatus(curWheel, map)
        end

        if mainPanelStatus == nil then
            if battleStatus == PVPArenaBattleStatus.InBattle then
                mainPanelStatus = PVPArenaMainPanelStatus.InBattle
            else
                mainPanelStatus = PVPArenaMainPanelStatus.InWait
            end
        end

    end

    --- 对战图 默认设置
    --- 进入对阵图 由于会从对阵图进入别的界面 并且会切换对阵图 所以不能使用 matchChartType
    --- 1. 没设置过 根据 seasonFlag设置
    if self.matchChartType == nil then
        self.matchChartType = (seasonFlag == PVPArenaSeasonFullStatus.Final or seasonFlag == PVPArenaSeasonFullStatus.Closed) and Constants.PVPArenaMatchChartType.Final or Constants.PVPArenaMatchChartType.Group
    --- 2. 从休赛季 切换到 最终赛季
    elseif oldSeasonFlag == PVPArenaSeasonFullStatus.OffSeason and seasonFlag == PVPArenaSeasonFullStatus.Final then
        self.matchChartType = Constants.PVPArenaMatchChartType.Final
    end

    self.oldSeasonFlag = oldSeasonFlag
    self:SetSeasonFlag(seasonFlag)

    self:SetMainPanelStatus(mainPanelStatus)
end

---InitPlayerBattleMainPanelStatus
---@param curWheel number
---@param map table
function PVPArenaComponent:InitPlayerBattleMainPanelStatus(curWheel, map)
    local mainPanelStatus
    local matchChartTotalWheelNum = self:GetMatchChartTotalWheelNum()
    local isFinalDisplayWheel = curWheel == matchChartTotalWheelNum
    if not isFinalDisplayWheel then
        local playerId           = self:GetPlayerId()
        local expectPositions    = self.playerId2ExpectPosition[tostring(playerId)]
        local expectPosition     = expectPositions[curWheel]
        local expectPositionData = map[tostring(expectPosition)] or {}
        --- 当前轮找不到期望下标
        if checkNumber(expectPositionData.playerId) ~= playerId then
            local isFinalWheel = curWheel == (matchChartTotalWheelNum - 1)
            --- 检查 季军赛站位 玩家是否失败
            if isFinalWheel then
                local thirdPlaceR     = #expectPositions
                local thirdPlaceL     = thirdPlaceR - 1
                local expectPositionL = expectPositions[thirdPlaceL]
                local expectPositionR = expectPositions[thirdPlaceR]

                local positionDataL = checkTable(map[tostring(expectPositionL)])
                local positionDataR = checkTable(map[tostring(expectPositionR)])

                local leftIsPlayer  = checkNumber(positionDataL.playerId) == playerId
                local rightIsPlayer  = checkNumber(positionDataR.playerId) == playerId
                --- 找到玩家
                if leftIsPlayer or rightIsPlayer then
                    local isOwnDataL = next(positionDataL) ~= nil
                    local isOwnDataR = next(positionDataR) ~= nil
                    --- 比分不同 也就是不为0 则打过了 没有下一轮 则是观赛状态
                    if isOwnDataL and isOwnDataR and checkNumber(positionDataL.score) ~= checkNumber(positionDataR.score) then
                        mainPanelStatus = PVPArenaMainPanelStatus.WatchTheMatch
                    elseif (leftIsPlayer and isOwnDataL and not isOwnDataR) or
                            (rightIsPlayer and isOwnDataR and not isOwnDataL) then
                        mainPanelStatus = PVPArenaMainPanelStatus.InMatch
                    end

                else
                    mainPanelStatus = PVPArenaMainPanelStatus.WatchTheMatch
                end
            elseif curWheel > 1 then
                --- 要检查上轮是否打完
                expectPosition     = expectPositions[curWheel - 1]
                expectPositionData = map[tostring(expectPosition)] or {}
                local rivalPosition = expectPosition % 2 == 0 and (expectPosition - 1) or (expectPosition + 1)
                local rivalPositionData = map[tostring(rivalPosition)]
                --- 如果(上轮期望站位是该玩家 并且 该玩家的分数 小于 对手的分数) 或者 上轮期望站位不是是该玩家 则是观赛状态
                if (checkNumber(expectPositionData.playerId) == playerId and checkNumber(expectPositionData.score) < checkNumber(rivalPositionData.score)) or checkNumber(expectPositionData.playerId) ~= playerId then
                    mainPanelStatus = PVPArenaMainPanelStatus.WatchTheMatch
                end

            end
        else
            --- 检查有没有对手
            local rivalPosition = expectPosition % 2 == 0 and (expectPosition - 1) or (expectPosition + 1)
            local positionData = map[tostring(rivalPosition)]
            if positionData == nil then
                mainPanelStatus = PVPArenaMainPanelStatus.InMatch
            end
        end
    else
        --- 有冠军了 变为 观赛状态
        mainPanelStatus = PVPArenaMainPanelStatus.WatchTheMatch
    end

    return mainPanelStatus
end

---InitPlayerId2Group
---初始化 玩家id -> X组
function PVPArenaComponent:InitPlayerId2Group()
    if self.playerId2Group then
        return
    end
    ---@type PVPArenaDojo
    local pvpArenaDojo        = self:GetPVPArenaDojo()

    local map                 = pvpArenaDojo.map
    local numberOfContestants = self:GetNumberOfContestants()
    local playerId2Group      = {}
    ---小组个数
    local groupCount          = GroupCount
    ---每组人数
    local oneGroupCount = numberOfContestants / groupCount
    local groupIndex = 1

    local t = {}
    local aByte = string.byte("a")
    local Number2char = function(index)
        local char = string.upper(string.char(index - 1 + aByte))
        t[index] = localize("_name_组", {_name_ = char})
        return t[index]
    end
    for i = 1, numberOfContestants do
        local positionData = map[tostring(i)]
        if positionData then
            local playerId = positionData.playerId
            local text = t[groupIndex] or Number2char(groupIndex)
            playerId2Group[tostring(playerId)] = {text = text, groupIndex = groupIndex, position = i}
            if i % oneGroupCount == 0 then
                groupIndex = groupIndex + 1
            end
        end
    end
    self.playerId2Group = playerId2Group
end

---InitMatchWheelInfo
---初始化 64强 32强 等相关信息
function PVPArenaComponent:InitMatchWheelInfo()
    ---@type Constants.PVPArenaSeasonFullStatus
    local seasonFlag    = self:GetSeasonFlag()
    local text
    local isNum = true

    local pvpArenaDojo = self:GetPVPArenaDojo()
    local battleRound  = checkNumber(pvpArenaDojo.battleRound)

    --- 小组赛打了多少轮
    local groupWheelCount = self:GetGroupWheelCount()
    --local groupDisplayWheelCount = groupWheelCount + 1
    --- 最终赛打了多少轮
    local finalWheelCount = self:GetFinalWheelCount()
    --- 计算总共打多少轮
    local totalWheel = groupWheelCount + finalWheelCount
    if seasonFlag == Constants.PVPArenaSeasonFullStatus.Final or
            seasonFlag == Constants.PVPArenaSeasonFullStatus.Closed then

        battleRound = battleRound + groupWheelCount
        --- 2表示 决赛 半决赛
        if battleRound >= (totalWheel - 1) then
            text = battleRound == (totalWheel - 1) and localize("半决赛") or localize("决赛")
            isNum = false
        else
            text = checkInt(2 ^ (totalWheel - battleRound))
        end

    else
        text = checkInt(2 ^ (totalWheel - battleRound))

    end

    ---@field roundOfNumber string 多少强
    self.roundOfNumber = text
    ---@field roundOfNumberIsNum boolean 多少强 是否是数字
    self.roundOfNumberIsNum = isNum
end

function PVPArenaComponent:InitQuizzedMap()
    ---@type PVPArenaDojo
    local pvpArenaDojo = self:GetPVPArenaDojo()
    --- 参赛玩家不投票不处理
    if checkNumber(pvpArenaDojo.identity) == Constants.PVPArenaIdentity.Player then return end
    if next(self.quizzedMap) then return end

    local playerId2Group = self:GetPlayerId2Group()
    local quizzed    = checkTable(pvpArenaDojo.quizzed)
    local playerId2StartPosition = {}
    ---{[玩家id] = 玩家是否淘汰 0 没有淘汰 1 已淘汰}
    local quizzedMap = {}
    for i, playerId in pairs(quizzed) do
        local id = tostring(playerId)
        quizzedMap[id] = self.quizzedMap[id] or 0
        local position = playerId2Group[id].position
        playerId2StartPosition[id] = position
    end
    self.quizzedMap = quizzedMap

    return playerId2StartPosition
end

---InitPlayerId2ExpectPosition
---@param playerId2StartPosition table 传入的是 非参赛玩家所投票的 玩家id -> 起始站位
function PVPArenaComponent:InitPlayerId2ExpectPosition(playerId2StartPosition)
    if self.playerId2ExpectPosition then
        return
    end
    ---@type PVPArenaEntryDojo
    local pvpArenaEntryDojo = self:GetPVPArenaEntryDojo()
    if checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Player then
        local playerId2Group = self:GetPlayerId2Group()
        local playerId       = self:GetPlayerId()
        local position       = playerId2Group[tostring(playerId)].position
        playerId2StartPosition = {[tostring(playerId)] = position}
    end

    --print(table.toString(playerId2StartPosition))
    self.playerId2ExpectPosition = self:CalcPlayerExpectPositionByStartPosition(playerId2StartPosition)
    --print("self.playerId2ExpectPosition", table.toString(self.playerId2ExpectPosition))
end

---StartCountdown
---开启倒计时
function PVPArenaComponent:StartCountdown()
    ---@type PVPArenaEntryDojo
    local pvpArenaEntryDojo = self:GetPVPArenaEntryDojo()
    -- local time              = pvpArenaEntryDojo.nextStageLeftSeconds
    --- 存在则不新建
    if self._countdown then return end
    --- 不处理大于三天情况
    --if time > CountDownTime then return end
    --- 开启一个3天的倒计时
    self._countdown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if self.startRequest then return end

        pvpArenaEntryDojo.nextStageLeftSeconds = pvpArenaEntryDojo.nextStageLeftSeconds - 1
        local isNeedRequest = pvpArenaEntryDojo.nextStageLeftSeconds <= 0
        if pvpArenaEntryDojo.seasonStatus == Constants.PVPArenaSeasonStatus.Battle then
            pvpArenaEntryDojo.battleNextStageLeftSeconds = pvpArenaEntryDojo.battleNextStageLeftSeconds - 1
            isNeedRequest = isNeedRequest or pvpArenaEntryDojo.battleNextStageLeftSeconds <= 0
        end

        Events.Broadcast(Constants.EventNames.PVPArenaCountDownUpdate)

        if not isNeedRequest then
            return
        end

        if self.isEntryPVP then
            self:RequestHome()
        else
            self:RequestEntry()
        end

    end, CountDownTime, false, true)
end
---RemoveCountdown
---移除倒计时
function PVPArenaComponent:RemoveCountdown()
    if self._countdown == nil then return end

    CDTimerModule.GetInstance():RemoveCD(self._countdown)
    self._countdown = nil
end


