function PVPArenaComponent:RequestEntry()

    GameUtils.Request(Interfaces.PVPArenaEntry, {}, function(request, response)
        self:InitEntry(response.data)
        Events.Broadcast(Constants.EventNames.PVPArenaRequestEntrySuccess)
    end)
end

---RequestHome
---请求home数据
function PVPArenaComponent:RequestHome(body)
    self.startRequest = true


    return GameUtils.Request(Interfaces.PVPArenaHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        
        self:InitHomeResponseData(response.data, body)

        self.startRequest = nil
    end)
end

function PVPArenaComponent:InitHomeResponseData(jsonData, body)
    --print(table.serialize(jsonData))
    --- 更新home data
    self:Initial(jsonData)

    --- 再战斗准备阶段 对手准备状态才有用
    if checkNumber(jsonData.battleStatus) ~= Constants.PVPArenaBattleStatus.Prepare then
        self:SetRivalReadyState(false)
        self:SetRivalMatchRound()
        --self:SetBattleServer()
    end

    

    -- --- 如果弹出 战前准备界面 则不通知 请求home success
    -- if isBroadcastHome then
    --     --- 发送home 请求完成事件
    --     Events.Broadcast(Constants.EventNames.PVPArenaRequestHomeSuccess)
    -- end
    Events.Broadcast(Constants.EventNames.PVPArenaRequestHomeSuccess, true)

end

function PVPArenaComponent:CheckDialog()
    xTry(function ()
    
        local isPop = self:CheckResultDialog()
    
        ---如果是参赛玩家 再准备阶段的话 直接弹 战前准备界面
        local isPopReady = self:CheckPlayerReadyDialog()
        
        return isPop or isPopReady, isPopReady
    end)
end

function PVPArenaComponent:RequestSeasonRank(seasonId)
    --Arena/seasonRank
    if checkNumber(seasonId) <= 0 then
        Events.Broadcast(Constants.EventNames.PVPArenaRequestSeasonRankSuccess, seasonId)
        return
    end

    local seasonRank = self:GetSeasonRank(seasonId)
    if seasonRank then
        Events.Broadcast(Constants.EventNames.PVPArenaRequestSeasonRankSuccess, seasonId, seasonRank)
        return
    end

    GameUtils.Request(Interfaces.PVPArenaSeasonRank, {seasonId = seasonId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local data = response.data
        self:InitSeasonRankResponseData(seasonId, data)
    end)
end

function PVPArenaComponent:InitSeasonRankResponseData(seasonId, data)
    local seasonRank = checkTable(data.rank)
    self:SetSeasonRank(seasonId, seasonRank)
    --- 发送home 请求完成事件
    Events.Broadcast(Constants.EventNames.PVPArenaRequestSeasonRankSuccess, seasonId, seasonRank)
end

---RequestMatcher
---请求参赛者信息成功
---@param playerId number 玩家id
function PVPArenaComponent:RequestMatcher(playerId)
    if playerId == nil then
        printError("RequestMatcher--->>>  not found playerId ")
        return
    end

    GameUtils.Request(Interfaces.PVPArenaMatcher, {matcherId = playerId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local data = response.data
        --- 发送请求参赛者信息成功 请求完成事件
        Events.Broadcast(Constants.EventNames.PVPArenaRequestMatcherSuccess, data, playerId)

    end)
end

function PVPArenaComponent:RequestQuiz(playerId)
    if playerId == nil then
        printError("RequestQuiz--->>>  not found playerId ")
        return
    end

    GameUtils.Request(Interfaces.PVPArenaQuiz, {matcherId = playerId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        self:InitQuizResponseData(playerId)
    end)
end

function PVPArenaComponent:InitQuizResponseData(playerId)
    local pvpArenaDojo = self:GetPVPArenaDojo()
    local quizzed = checkTable(pvpArenaDojo.quizzed)
    table.insert(quizzed, playerId)
    pvpArenaDojo.quizzed = quizzed
    pvpArenaDojo.quizTicketNum = checkNumber(pvpArenaDojo.quizTicketNum) - 1
    self.quizzedMap[tostring(playerId)] = 0

    --- 因为 从非pvp入口进入 主界面不会主动拉home 所以 重新初始化一次
    self:InitSeasonFlag()

    --- 添加投票玩家的 期望站位
    local playerId2Group = self:GetPlayerId2Group()
    local position = playerId2Group[tostring(playerId)].position
    local playerId2ExpectPosition = self:CalcPlayerExpectPositionByStartPosition({[tostring(playerId)] = position})

    table.merge(self.playerId2ExpectPosition, playerId2ExpectPosition)
    --print(playerId, table.toString(self.playerId2ExpectPosition))

    --- 发送投票 请求完成事件
    Events.Broadcast(Constants.EventNames.PVPArenaRequestQuizSuccess, playerId)
end

function PVPArenaComponent:RequestHistorySeason()
    GameUtils.Request(Interfaces.PVPArenaHistorySeason, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        --- 发送 往届第一 请求完成事件
        Events.Broadcast(Constants.EventNames.PVPArenaRequestHistorySeasonSuccess, response.data)
    end)
end

function PVPArenaComponent:RequestReply(position, cb)
    GameUtils.Request(Interfaces.PVPArenaReply, {position = position}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        --Events.Broadcast(Constants.EventNames.PVPArenaRequestReplySuccess, response.data)
        if cb then
            cb(response.data)
        end
    end)
end



