function PVPArenaComponent:CheckPlayerReadyDialog()

    local isPop = false
    ---@type PVPArenaEntryDojo
    local pvpArenaEntryDojo = self:GetPVPArenaEntryDojo()
    local isPlayer = checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Player
    local mainPanelStatus = self:GetMainPanelStatus()
    --- 是玩家 并且 再战前准备阶段 并且 非观赛状态
    if isPlayer and checkNumber(pvpArenaEntryDojo.battleStatus) == Constants.PVPArenaBattleStatus.Prepare and mainPanelStatus ~= Constants.PVPArenaMainPanelStatus.WatchTheMatch then
        --- 1. 找到对手
        local wheel = self:GetCurWheel()
        local rivalInfo, rivalPlayerId = self:CalcRivalInfoByWheel(wheel)
        if rivalInfo then
            --- 1.1 有对手 设置 通知 请求 home 接口成功为 false
            isPop = true

            --- 1.2 构造战前准备界面所需数据
            local playerId     = self:GetPlayerId()
            ---@type PVPArenaDojo
            local pvpArenaDojo = self:GetPVPArenaDojo()
            local matcherInfo  = pvpArenaDojo.matcherInfo
            local playerInfo   = matcherInfo[tostring(playerId)]
            local data = {
                playerInfo = playerInfo,
                playerId   = playerId,
                rivalInfo  = rivalInfo,
                rivalPlayerId = checkNumber(rivalPlayerId),
            }

            --- 1.3 弹出 战前准备界面
            -----@type PVPArenaUtils
            --local PVPArenaUtils  = import('Game.Utils.PVPArenaUtils')
            --local excludeDialogs = GameUtils.GetAllExcludeIds()
            --PVPArenaUtils.ShowPlayerReadyDialog(data, excludeDialogs)
            
            
            self:EnterBattleReady(data)
        end

    end

    if isPop == false and self.isEntryPVP then
        ---@type PVPArenaPlayerReadyDialog
        local pvpArenaLoadingEnv = self:GetPVPArenaLoadingEnv()
        if not isNull(pvpArenaLoadingEnv) then
            pvpArenaLoadingEnv:DestroyView()
            self:SetPVPArenaLoadingEnv(nil)
        end
    end

    return isPop
end

function PVPArenaComponent:CheckResultDialog()
    ---@type PVPArenaEntryDojo
    local pvpArenaEntryDojo = self:GetPVPArenaEntryDojo()
    local battleStatus = checkNumber(pvpArenaEntryDojo.battleStatus)
    local isAudience   = checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience
    if not (battleStatus == Constants.PVPArenaBattleStatus.InBattle or battleStatus == Constants.PVPArenaBattleStatus.Result) then
        return
    end
    local resultDialogData = {}
    local seasonId     = pvpArenaEntryDojo.seasonId

    local dialogId, updateEventName
    if isAudience then
        self:CheckAudienceResultDialog(resultDialogData, seasonId)
        dialogId = Constants.UITypeIds.PVPArenaQuizResultDialog
        updateEventName = Constants.EventNames.PVPArenaUpdateQuizResult
    else
        self:CheckPlayerResultDialog(resultDialogData, seasonId)
        dialogId = Constants.UITypeIds.PVPArenaMatchResultDialog
        updateEventName = Constants.EventNames.PVPArenaUpdateMatchResult
    end

    local isPop = next(resultDialogData) ~= nil
    if isPop then
        self:SetResultDialogHistoryRecord()
        self:PopResultDialog(dialogId, resultDialogData, updateEventName)
    end
    return isPop
end

---CheckAudienceResultDialog
---检查非参赛玩家 投票玩家 结果弹窗
---@param resultDialogData table
---@param seasonId number 赛季id
function PVPArenaComponent:CheckAudienceResultDialog(resultDialogData, seasonId)
    --- 1. 检查有没有投过票
    local quizzedMap = self.quizzedMap
    if next(quizzedMap) == nil then return end
    --- 2. 检查是否观众投票的玩家 全淘汰
    local survivalMap = {}
    for playerId, death in pairs(quizzedMap) do
        if death == 0 then
            survivalMap[playerId] = playerId
        end
    end
    if next(survivalMap) == nil then return end
    local pvpArenaDojo = self:GetPVPArenaDojo()
    local map          = pvpArenaDojo.map
    local curWheel     = self:GetCurWheel()

    local playerId2ExpectPosition = self.playerId2ExpectPosition
    --- 是否是 打的最后一轮 判断是 季军赛 还是 冠军赛
    for _, playerId in pairs(survivalMap) do
        --- 1. 检查当前玩家 当前赛季 当前轮是否弹过
        local playerIdSeasonRecord = self.resultDialogHistoryRecord[tostring(playerId)] or {}
        local seasonRecord         = playerIdSeasonRecord[tostring(seasonId)] or {}
        if checkNumber(seasonRecord[curWheel]) == 0 then
            playerId = checkNumber(playerId)
            local expectPositions    = playerId2ExpectPosition[tostring(playerId)]

            --- 检查上一轮是否有 比分
            local lastExpectPosition     = expectPositions[curWheel - 1]
            local lastExpectPositionData = map[tostring(lastExpectPosition)]
            if lastExpectPositionData then
                local rivalPosition = lastExpectPosition % 2 == 0 and lastExpectPosition - 1 or lastExpectPosition + 1
                local lastRivalPositionData = map[tostring(rivalPosition)] or {}
                if checkNumber(lastExpectPositionData.playerId) == playerId and (checkNumber(lastExpectPositionData.score) > 0 or checkNumber(lastRivalPositionData.score) > 0) then
                    local expectPosition     = expectPositions[curWheel]
                    local expectPositionData = map[tostring(expectPosition)]
                    if expectPositionData then
                        if checkNumber(expectPositionData.playerId) == playerId then
                            table.insert(resultDialogData, {wheel = curWheel, playerId = playerId, isWin = true})
                            seasonRecord[curWheel] = 1
                        else
                            quizzedMap[playerId] = 1
                            --- 失败的弹出条件
                            --- 当前轮失败 并且 上一轮 是该玩家
                            expectPosition     = expectPositions[curWheel - 1]
                            expectPositionData = map[tostring(expectPosition)]
                            if checkNumber(expectPositionData.playerId) == playerId then
                                table.insert(resultDialogData, {wheel = curWheel, playerId = playerId, isWin = false})
                                seasonRecord[curWheel] = 1
                            end
                        end
                    end
                end
            end

        end

        playerIdSeasonRecord[tostring(seasonId)] = seasonRecord
        self.resultDialogHistoryRecord[tostring(playerId)] = playerIdSeasonRecord
    end

end

---CheckPlayerResultDialog
---检查玩家参赛结果弹窗
---@param resultDialogData table
---@param seasonId number 赛季id
function PVPArenaComponent:CheckPlayerResultDialog(resultDialogData, seasonId)
    --- 参赛玩家
    --- 1. 检查是否冠军
    local playerId             = self:GetPlayerId()
    local pvpArenaDojo         = self:GetPVPArenaDojo()
    local curWheel             = self:GetCurWheel()
    local matchChartTotalWheelNum = self:GetMatchChartTotalWheelNum()
    local map                  = pvpArenaDojo.map
    local playerIdSeasonRecord = self.resultDialogHistoryRecord[tostring(playerId)] or {}
    local seasonRecord         = playerIdSeasonRecord[tostring(seasonId)] or {}

    if checkNumber(seasonRecord[curWheel]) > 0 then
        return
    end


    local playerId2ExpectPosition = self.playerId2ExpectPosition
    local expectPositions = playerId2ExpectPosition[tostring(playerId)]
    local expectPositionCount = #expectPositions
    local isLastDisplayWheel = curWheel == matchChartTotalWheelNum

    if isLastDisplayWheel then
        --- 处理 冠军 亚军 季军 殿军
        --- expectPositionCount 季军赛右侧玩家
        --- expectPositionCount - 1 季军赛左侧玩家
        local position     = expectPositions[curWheel]
        local positionData = map[tostring(position)] or {}
        if checkNumber(positionData.playerId) == playerId then
            table.insert(resultDialogData, {rank = 1, isShowResult = true})
            seasonRecord[curWheel] = 1
        else
            ---1. 获取冠军上轮的站位
            position = expectPositions[expectPositionCount - 3]
            ---2. 获取亚军站位 因为 不是冠军 所以根据 冠军站位单双判断 亚军位置
            local secondPlacePosition = position % 2 == 0 and (position - 1) or (position + 1)
            ---3. 检查 是否是亚军 季军 殿军
            local thirdPlacePotionL = expectPositions[expectPositionCount - 1]
            local thirdPlacePotionR = expectPositions[expectPositionCount]

            local thirdPlacePotionDataL = map[tostring(thirdPlacePotionL)]
            local thirdPlacePotionDataR = map[tostring(thirdPlacePotionR)]

            local winL = checkNumber(thirdPlacePotionDataL.score) > checkNumber(thirdPlacePotionDataR.score)
            local thirdPlacePotion = winL and thirdPlacePotionDataL or thirdPlacePotionDataR
            local forthPlacePotion = winL and thirdPlacePotionDataR or thirdPlacePotionDataL

            local t = {
                [2] = secondPlacePosition,
                [3] = thirdPlacePotion,
                [4] = forthPlacePotion,
            }
            for rank, placePosition in ipairs(t) do
                positionData = map[tostring(placePosition)]
                if positionData and checkNumber(positionData.playerId) == playerId then
                    table.insert(resultDialogData, {rank = rank, isShowResult = true})
                    seasonRecord[curWheel] = 1
                    break
                end
            end

        end

    else
        --- 最终成绩弹出条件
        --- 当前轮期望站位不是该玩家 并且 上一轮期望站位是该玩家
        ---
        --- 晋级条件
        --- 当前轮期望站位是该玩家
        local expectPosition = expectPositions[curWheel]
        local positionData = map[tostring(expectPosition)]
        --- 期望站位无人 则不处理
        if positionData == nil then return end
        local lastPosition = expectPositions[curWheel - 1]
        local lastPositionData = map[tostring(lastPosition)]
        if lastPositionData then
            local rivalPosition = lastPosition % 2 == 0 and lastPosition - 1 or lastPosition + 1
            local lastRivalPositionData = map[tostring(rivalPosition)] or {}
            if checkNumber(lastPositionData.playerId) == playerId and (checkNumber(lastPositionData.score) > 0 or checkNumber(lastRivalPositionData.score) > 0) then
                local isShowResult = checkNumber(positionData.playerId) ~= playerId
                local offset = isShowResult and 1 or 0
                table.insert(resultDialogData, {rank = 2 ^ (matchChartTotalWheelNum - curWheel + offset), isShowResult = isShowResult})
                seasonRecord[curWheel] = 1
            end
        end

    end
    playerIdSeasonRecord[tostring(seasonId)] = seasonRecord
    self.resultDialogHistoryRecord[tostring(playerId)] = playerIdSeasonRecord
    --print(table.toString(seasonRecord))
end

---PopResultDialog
---@param dialogId Constants.UITypeIds
---@param resultDialogData table
---@param updateEventName string
function PVPArenaComponent:PopResultDialog(dialogId, resultDialogData, updateEventName)
    --- 如果结果还在显示 则发送对应的事件更新数据
    local idMap = {[dialogId] = true}
    if GameUtils.CheckIsShowDialogByIdMap(idMap) then
        Events.Broadcast(updateEventName, resultDialogData)
        return
    end

    ---@type PVPArenaUtils
    local PVPArenaUtils     = import('Game.Utils.PVPArenaUtils')
    PVPArenaUtils.ShowResultDialog(dialogId, resultDialogData)
end


