---CalcWheel
---@param count number
function PVPArenaComponent:CalcWheel(count)
    local wheel = 1
    while (count / 2) ~= 1 do
        wheel = wheel + 1
        count = count / 2
    end
    return wheel
end

---CalcWheelByPosition
---根据对战表站位计算能展示几轮
---@param position number 对战表站位
function PVPArenaComponent:CalcDisplayWheelByPosition(position)
    --- 所有轮(小组赛轮数+最终赛轮数+冠军展示轮)的最大范围
    local wheelScope = self:GetAllWheelScope()
    local displayWheelCount
    if position <= self:GetGroupEndNumber() then
        displayWheelCount = self:GetGroupWheelCount() + 1
    else
        displayWheelCount = self:GetMatchChartTotalWheelNum()
    end

    local wheel = 1
    local leftBoundary, rightBoundary
    for i = displayWheelCount, 1, -1 do
        local scope = wheelScope[i]
        leftBoundary, rightBoundary = SafeUnpack(scope)
        --- 找到 所在轮数
        if position >= leftBoundary and position <= rightBoundary then
            wheel = i
            break
        end
    end

    return wheel, leftBoundary, rightBoundary
end

---CalcCurWheelRivalInfo
---获取当前轮对手信息
function PVPArenaComponent:CalcRivalInfoByWheel(wheel)

    local matchChartTotalWheelNum = self:GetMatchChartTotalWheelNum()
    --- 最终展示轮直接返回
    if wheel == matchChartTotalWheelNum then return end

    local rivalInfo, rivalPlayerId
    local playerId           = self:GetPlayerId()
    local expectPositions    = self.playerId2ExpectPosition[tostring(playerId)]
    local expectPosition     = expectPositions[wheel]
    ---@type PVPArenaDojo
    local pvpArenaDojo = self:GetPVPArenaDojo()
    local map          = checkTable(pvpArenaDojo.map)
    local expectPositionData = map[tostring(expectPosition)]

    local InitRivalData = function(rivalPosition)
        local positionData = map[tostring(rivalPosition)]
        if positionData then
            rivalPlayerId = positionData.playerId
            local matcherInfo = pvpArenaDojo.matcherInfo
            rivalInfo = matcherInfo[tostring(rivalPlayerId)]
        end
    end

    if expectPositionData and checkNumber(expectPositionData.playerId) == playerId then
        local rivalPosition = expectPosition % 2 == 0 and (expectPosition - 1) or (expectPosition + 1)
        InitRivalData(rivalPosition)
    --- 打的最后一轮 检查季军赛站位
    elseif wheel == (matchChartTotalWheelNum - 1) then
        local thirdPlaceR     = #expectPositions
        local thirdPlaceL     = thirdPlaceR - 1
        local expectPositionL = expectPositions[thirdPlaceL]
        local expectPositionR = expectPositions[thirdPlaceR]

        local t = {expectPositionL, expectPositionR}
        local t1 = {expectPositionR, expectPositionL}
        for i, position in ipairs(t) do
            expectPositionData = map[tostring(position)]
            if expectPositionData and checkNumber(expectPositionData.playerId) == playerId then
                InitRivalData(t1[i])
                break
            end
        end

    end

    return rivalInfo, rivalPlayerId
end

---CalcTotalQuizRewardsNumByWheel
---根据轮数计算 总投票奖励
---@param wheel number       已经打了多少轮
---@param wheelIsWin boolean 再这轮是否获胜
function PVPArenaComponent:CalcTotalQuizRewardsNumByWheel(wheel, wheelIsWin)
    ---当前轮是否获胜 获胜 获胜奖励  失败 失败奖励
    local totalNum = wheelIsWin and self.quizSuccessRewardsNum or self.quizFailRewardsNum
    --- 加上前几轮 奖励
    totalNum = totalNum + (wheel <= 1 and 0 or (wheel - 1)) * self.quizSuccessRewardsNum
    return totalNum
end

---CalePlayerExpectPositionByStartPosition
---根据玩家起始站位计算玩家期望站位
---@param playerId2StartPosition table<string, number> 起始站位列表{[playerId] = position, [playerId] = position}
function PVPArenaComponent:CalcPlayerExpectPositionByStartPosition(playerId2StartPosition)
    if playerId2StartPosition == nil then
        return {}
    end
    --- 对阵图总轮数
    local totalWheel          = self:GetMatchChartTotalWheelNum()
    --- 参数人数
    local numberOfContestants = self:GetNumberOfContestants()
    local totalNumber = 0
    local t = {}
    local factor = 0.5
    --- 计算每一轮的站位
    local CalcWheelPosition = function(wheelPositionList, position, wheel)
        --- 每一轮的站位
        local wheelPosition = math.ceil(position * factor ^ (wheel - 1))
        local realPosition = wheelPosition + totalNumber
        --- 公式  参数人数 * 一个等比数列的和(1 + 1/2 + 1/4)
        totalNumber = checkInt(numberOfContestants * (1 - factor ^ wheel) / factor)
        if wheel == totalWheel then
            --- 由于会把 pvpArenaDojo.map 中 季军赛双方站位放到冠军前面 所以这里直接交换站位
            --- 插入冠军站位
            table.insert(wheelPositionList, totalNumber + 2)
            --- 季军赛左侧站位
            table.insert(wheelPositionList, totalNumber)
            --- 季军赛右侧站位
            table.insert(wheelPositionList, totalNumber + 1)
        else
            table.insert(wheelPositionList, realPosition)
        end
    end

    for wheel = 1, totalWheel do
        for playerId, position in pairs(playerId2StartPosition) do
            t[playerId] = t[playerId] or {}
            CalcWheelPosition(t[playerId], position, wheel)
        end
    end

    return t
end

---CalcBattleNextWheelSeconds
---计算下轮剩余时间
function PVPArenaComponent:CalcBattleNextWheelSeconds()
    local seasonFlag           = self:GetSeasonFlag()
    local pvpArenaEntryDojo    = self:GetPVPArenaEntryDojo()
    local isFinal = seasonFlag == Constants.PVPArenaSeasonFullStatus.Final
    local OneWheelSeconds      = isFinal and self:GetFinalOneWheelSeconds() or self:GetGroupOneWheelSeconds()
    local BattlePrepareSeconds = self:GetBattlePrepareSecond()
    local ResultSeconds        = self:GetRewardsResultSecond()
    local InBattleSeconds      = OneWheelSeconds - BattlePrepareSeconds - ResultSeconds

    local battleStatus = checkNumber(pvpArenaEntryDojo.battleStatus)
    local battleNextStageLeftSeconds = pvpArenaEntryDojo.battleNextStageLeftSeconds
    local second = battleNextStageLeftSeconds
    if battleStatus == Constants.PVPArenaBattleStatus.Wait then
        second = second + OneWheelSeconds
    elseif battleStatus == Constants.PVPArenaBattleStatus.Prepare then
        second = second + InBattleSeconds + ResultSeconds
    elseif battleStatus == Constants.PVPArenaBattleStatus.InBattle then
        second = second + ResultSeconds
    end

    return second
end


