function PVPArenaComponent:GetNowMatcherWheel()
    ---1. 获取打了多少轮 (对阵图 显示的轮数) - 1
    local displayWheel    = self:GetCurWheel()
    local matcherWheel    = displayWheel - 1
    --local groupDisplayWheelCount = self:GetGroupWheelCount() + 1
    ---2. 检查是否进入 最终赛
    --local seasonFlag      = self:GetSeasonFlag()
    --local isFinal         = seasonFlag == Constants.PVPArenaSeasonFullStatus.Final
    local wheelScope       = self:GetAllWheelScope()
    --local finalWheelScope = self:GetFinalWheelScope()
    --local wheelScope      = isFinal and finalWheelScope or groupWheelScope
    local scope = wheelScope[matcherWheel]
    return scope, displayWheel == self:GetMatchChartTotalWheelNum()
end

