function PVPArenaComponent:GetSeasonStageLeftSeconds()
    local seconds = 0
    local pvpArenaEntryDojo = self:GetPVPArenaEntryDojo()
    local seasonFlag        = self:GetSeasonFlag()
    local mainPanelStatus   = self:GetMainPanelStatus()
    local isAudience        = checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience

    if seasonFlag == PVPArenaSeasonFullStatus.Quiz then
        local offset = isAudience and 0 or self:GetNoticeSecond()
        seconds = pvpArenaEntryDojo.nextStageLeftSeconds + offset

    elseif seasonFlag == PVPArenaSeasonFullStatus.Notice then
        seconds = pvpArenaEntryDojo.nextStageLeftSeconds

    elseif checkNumber(pvpArenaEntryDojo.seasonStatus) == Constants.PVPArenaSeasonStatus.Battle then
        if seasonFlag == PVPArenaSeasonFullStatus.OffSeason then
            --- 这时应该再 PVPArenaBattleStatus.Wait
            seconds = pvpArenaEntryDojo.battleNextStageLeftSeconds
        elseif isAudience or mainPanelStatus == Constants.PVPArenaMainPanelStatus.WatchTheMatch then
            local groupWheelCount = self:GetGroupWheelCount()
            local pvpArenaDojo    = self:GetPVPArenaDojo()
            local battleRound     = checkNumber(pvpArenaDojo.battleRound)
            --battleRound = battleRound < 0 and 1 or battleRound + 1
            local battleStatus    = pvpArenaEntryDojo.battleStatus
            if battleStatus >= Constants.PVPArenaBattleStatus.Prepare then
                battleRound = battleRound - 1
            end
            battleRound = battleRound + 1
            if seasonFlag == PVPArenaSeasonFullStatus.Group then
                local nextWheelSeconds = self:CalcBattleNextWheelSeconds()
                local wheel = groupWheelCount - battleRound
                wheel = math.max(wheel, 0)
                --- 下一轮时间 + 小组还会打多少轮  * 单轮时间
                seconds = nextWheelSeconds + wheel * self:GetGroupOneWheelSeconds()

            elseif seasonFlag == PVPArenaSeasonFullStatus.Final then
                local wheelCount       = self:GetFinalWheelCount()
                local nextWheelSeconds = self:CalcBattleNextWheelSeconds()

                local wheel = wheelCount - battleRound
                wheel = math.max(wheel, 0)
                --- 下一轮时间 + 小组还会打多少轮  * 单轮时间
                seconds = nextWheelSeconds + wheel * self:GetFinalOneWheelSeconds()
            end
        else
            seconds = self:CalcBattleNextWheelSeconds()
        end

    end

    return seconds
end

