function PVPArenaComponent:OnEventReceivePacketSuccess(packetId, data)
    if packetId == Constants.Packets.PVPArenaReceiveRivalReady then
        print("Constants.Packets.PVPArenaReceiveRivalReady ", table.toString(data))
        local result = checkNumber(data.result)
        self:SetRivalReadyState(result == 1)
        self:SetBattleServer(data.server)
        self:SetRivalMatchRound(checkNumber(data.matchRound))
        Events.Broadcast(Constants.EventNames.PVPArenaRivalReady)
    -- elseif packetId == Constants.Packets.CommonError then
    --     local msg = checkNumber(Constants.Packets.CommonError)
    end
end

function PVPArenaComponent:EnterBattleReady(data)
    ---@type PVPArenaPlayerReadyDialog
    local pvpArenaLoadingEnv = self:GetPVPArenaLoadingEnv()
    local arg = { id = Constants.UITypeIds.BattleScene, parameters = data }
    if not isNull(pvpArenaLoadingEnv) then
        KTool.SetActive(pvpArenaLoadingEnv.controller.gameObject, true)
        pvpArenaLoadingEnv:SetArg(arg, nil, Constants.LoadingType.PVPArena)
    else

        GameUtils.OpenLoadingPanel(arg, nil, Constants.LoadingType.PVPArena)
    end
end

