function PVPArenaComponent:ReleaseResources()
    self:SetIsEntryPVP(false)
    
    self:RemoveCountdown()
    --- 1. 释放建筑物
    self:ReleaseMansion()
end

function PVPArenaComponent:ReleaseMansion()
    self:ReleaseMansionRootGo()
    self:ReleaseBundle()
end

---ReleaseMansionRootGo
---release
function PVPArenaComponent:ReleaseMansionRootGo()
    if isNull(self.mansionRootGo) then return end
    self.groupVenuePos = nil
    self.finalVenuePos = nil
    KTool.DestroyGameObjectChildren(self.mansionRootGo)
    self.mansionGo = nil
    KTool.SafeDelete(self.mansionRootGo)
    self.mansionRootGo = nil
end

